"""Canonical identity for compiler-emitted generated-decode descriptors."""

from __future__ import annotations

from array import array
import base64
import binascii
import hashlib
import json
from collections.abc import Mapping
from math import isfinite
import struct
import sys
from types import MappingProxyType
from typing import Any


RUNTIME_DESCRIPTOR_DIGEST_DOMAIN = "kestrel.generated_decode.runtime_descriptor"
RUNTIME_DESCRIPTOR_DIGEST_SCHEMA_VERSION = 1
PACKED_TAPE_ENCODING = "dense_i32_le_b64"
PACKED_TAPE_SCHEMA_VERSION = 1
# Large generated waveform decoders use up to 24.41 MiB of dense tape.
PACKED_TAPE_MAX_BYTES = 32 * 1024 * 1024
_PACKED_TAPE_LAYOUT = {
    "n_fields": 6,
    "opcode": 0,
    "start_block": 1,
    "end_block": 2,
    "layer": 3,
    "fill": -1,
    "page_sequence_end": 4,
    "output_sequence_end": 5,
}
_HANDOFF_TAPE_LAYOUT = {
    **_PACKED_TAPE_LAYOUT,
    "n_fields": 8,
    "pipeline_handoff_flags": 6,
}
_INT32_MIN = -(1 << 31)
_INT32_MAX = (1 << 31) - 1
_MAPPING_PROXY_TYPE = type(MappingProxyType({}))


class RuntimeDescriptorIdentityError(ValueError):
    """A runtime descriptor cannot be represented by the canonical schema."""


def _has_canonical_tape_layout(value: Any) -> bool:
    return (
        isinstance(value, Mapping)
        and any(
            set(value) == set(layout)
            and all(type(value[name]) is int and value[name] == expected
                    for name, expected in layout.items())
            for layout in (_PACKED_TAPE_LAYOUT, _HANDOFF_TAPE_LAYOUT)
        )
    )


def _packed_tape_byte_count(num_ctas: int, max_qlen: int, n_fields: int) -> int:
    byte_count = (num_ctas + num_ctas * max_qlen * n_fields) * 4
    if byte_count > PACKED_TAPE_MAX_BYTES:
        raise RuntimeDescriptorIdentityError(
            "packed generated decode tape exceeds its size bound"
        )
    return byte_count


def pack_runtime_descriptor_tape(descriptor: Mapping[str, Any]) -> dict:
    """Return a transport copy with its canonical dense int32 tape packed."""

    if not isinstance(descriptor, Mapping):
        raise RuntimeDescriptorIdentityError("runtime descriptor must be an object")
    tape = descriptor.get("tape")
    if not isinstance(tape, Mapping):
        raise RuntimeDescriptorIdentityError(
            "generated decode packed tape must be an object"
        )
    required = {"instr", "layout", "max_qlen", "num_ctas", "qlen"}
    if set(tape) not in (required, required | {"is_queue"}):
        raise RuntimeDescriptorIdentityError(
            "generated decode packed tape has unexpected or missing fields"
        )
    num_ctas = tape.get("num_ctas")
    max_qlen = tape.get("max_qlen")
    if (
        type(num_ctas) is not int
        or num_ctas <= 0
        or type(max_qlen) is not int
        or max_qlen <= 0
        or type(descriptor.get("num_ctas")) is not int
        or descriptor.get("num_ctas") != num_ctas
    ):
        raise RuntimeDescriptorIdentityError(
            "generated decode packed tape has invalid dimensions"
        )
    if not _has_canonical_tape_layout(tape.get("layout")):
        raise RuntimeDescriptorIdentityError(
            "generated decode packed tape has invalid layout"
        )
    if "is_queue" in tape and type(tape["is_queue"]) is not bool:
        raise RuntimeDescriptorIdentityError(
            "generated decode packed tape has invalid queue flag"
        )
    qlen = tape.get("qlen")
    instr = tape.get("instr")
    if not isinstance(qlen, (list, tuple)) or len(qlen) != num_ctas:
        raise RuntimeDescriptorIdentityError(
            "generated decode packed tape has invalid queue lengths"
        )
    if not isinstance(instr, (list, tuple)) or len(instr) != num_ctas:
        raise RuntimeDescriptorIdentityError(
            "generated decode packed tape has invalid CTA rows"
        )

    n_fields = tape["layout"]["n_fields"]
    expected_byte_count = _packed_tape_byte_count(num_ctas, max_qlen, n_fields)
    values = array("i")
    if values.itemsize != 4:
        raise RuntimeDescriptorIdentityError(
            "generated decode packed tape requires 32-bit C integers"
        )
    for value in qlen:
        if type(value) is not int or not 0 <= value <= max_qlen:
            raise RuntimeDescriptorIdentityError(
                "generated decode packed tape has invalid queue lengths"
            )
        values.append(value)
    for cta, rows in enumerate(instr):
        if not isinstance(rows, (list, tuple)) or len(rows) != max_qlen:
            raise RuntimeDescriptorIdentityError(
                "generated decode packed tape has invalid CTA rows"
            )
        for row_index, row in enumerate(rows):
            if not isinstance(row, (list, tuple)) or len(row) != n_fields:
                raise RuntimeDescriptorIdentityError(
                    "generated decode packed tape has invalid instruction rows"
                )
            for value in row:
                if (
                    type(value) is not int
                    or not _INT32_MIN <= value <= _INT32_MAX
                    or row_index >= qlen[cta]
                    and value != -1
                ):
                    raise RuntimeDescriptorIdentityError(
                        "generated decode packed tape has noncanonical int32 rows"
                    )
                values.append(value)
            if (n_fields == 8 and row_index < qlen[cta]
                    and (not 0 <= row[6] <= 3 or row[7] != -1)):
                raise RuntimeDescriptorIdentityError(
                    "generated decode packed tape has invalid handoff fields")
    if sys.byteorder != "little":
        values.byteswap()
    raw = values.tobytes()
    if len(raw) != expected_byte_count:
        raise RuntimeDescriptorIdentityError(
            "generated decode packed tape has invalid byte length"
        )
    packed_tape = {
        "packed_schema_version": PACKED_TAPE_SCHEMA_VERSION,
        "encoding": PACKED_TAPE_ENCODING,
        "data": base64.b64encode(raw).decode("ascii"),
        "layout": dict(tape["layout"]),
        "max_qlen": max_qlen,
        "num_ctas": num_ctas,
    }
    if "is_queue" in tape:
        packed_tape["is_queue"] = tape["is_queue"]
    result = dict(descriptor)
    result["tape"] = packed_tape
    return result


def expand_runtime_descriptor_tape(descriptor: Mapping[str, Any]) -> dict:
    """Expand a packed transport tape; preserve legacy list-form descriptors."""

    if not isinstance(descriptor, Mapping):
        raise RuntimeDescriptorIdentityError("runtime descriptor must be an object")
    tape = descriptor.get("tape")
    if not isinstance(tape, Mapping) or "packed_schema_version" not in tape:
        return dict(descriptor)
    fields = {
        "packed_schema_version",
        "encoding",
        "data",
        "layout",
        "max_qlen",
        "num_ctas",
    }
    if set(tape) not in (fields, fields | {"is_queue"}):
        raise RuntimeDescriptorIdentityError(
            "packed generated decode tape has invalid fields"
        )
    if (
        type(tape.get("packed_schema_version")) is not int
        or tape["packed_schema_version"] != PACKED_TAPE_SCHEMA_VERSION
        or tape.get("encoding") != PACKED_TAPE_ENCODING
    ):
        raise RuntimeDescriptorIdentityError(
            "unsupported packed generated decode tape codec"
        )
    if not _has_canonical_tape_layout(tape.get("layout")):
        raise RuntimeDescriptorIdentityError(
            "packed generated decode tape has invalid layout"
        )
    if "is_queue" in tape and type(tape["is_queue"]) is not bool:
        raise RuntimeDescriptorIdentityError(
            "packed generated decode tape has invalid queue flag"
        )
    num_ctas = tape.get("num_ctas")
    max_qlen = tape.get("max_qlen")
    if (
        type(num_ctas) is not int
        or num_ctas <= 0
        or type(max_qlen) is not int
        or max_qlen <= 0
        or type(descriptor.get("num_ctas")) is not int
        or descriptor.get("num_ctas") != num_ctas
    ):
        raise RuntimeDescriptorIdentityError(
            "packed generated decode tape has invalid dimensions"
        )
    n_fields = tape["layout"]["n_fields"]
    byte_count = _packed_tape_byte_count(num_ctas, max_qlen, n_fields)
    encoded = tape.get("data")
    if not isinstance(encoded, str) or len(encoded) != 4 * ((byte_count + 2) // 3):
        raise RuntimeDescriptorIdentityError(
            "packed generated decode tape has invalid byte length"
        )
    try:
        raw = base64.b64decode(encoded, validate=True)
    except (binascii.Error, ValueError) as exc:
        raise RuntimeDescriptorIdentityError(
            "packed generated decode tape has invalid base64"
        ) from exc
    if len(raw) != byte_count or base64.b64encode(raw).decode("ascii") != encoded:
        raise RuntimeDescriptorIdentityError(
            "packed generated decode tape is not canonical"
        )

    qlen = list(struct.unpack_from(f"<{num_ctas}i", raw))
    if any(length < 0 or length > max_qlen for length in qlen):
        raise RuntimeDescriptorIdentityError(
            "packed generated decode tape has invalid queue lengths"
        )
    instr = []
    rows = list(
        map(
            list,
            struct.iter_unpack(f"<{n_fields}i", memoryview(raw)[num_ctas * 4 :]),
        )
    )
    offset = 0
    for cta in range(num_ctas):
        cta_rows = rows[offset : offset + max_qlen]
        offset += max_qlen
        if any(value != -1 for row in cta_rows[qlen[cta] :] for value in row):
            raise RuntimeDescriptorIdentityError(
                "packed generated decode tape has noncanonical padding"
            )
        if n_fields == 8 and any(
            not 0 <= row[6] <= 3 or row[7] != -1
            for row in cta_rows[:qlen[cta]]
        ):
            raise RuntimeDescriptorIdentityError(
                "packed generated decode tape has invalid handoff fields")
        instr.append(cta_rows)
    expanded_tape = {
        "instr": instr,
        "layout": dict(tape["layout"]),
        "max_qlen": max_qlen,
        "num_ctas": num_ctas,
        "qlen": qlen,
    }
    if "is_queue" in tape:
        expanded_tape["is_queue"] = tape["is_queue"]
    result = dict(descriptor)
    result["tape"] = expanded_tape
    return result


def _canonical_json_value(value: Any, *, path: str) -> Any:
    """Copy one strict JSON value without Python's bool/integer coercions."""

    value_type = type(value)
    if value is None or value_type in (bool, int, str):
        return value
    if value_type is float:
        if not isfinite(value):
            raise RuntimeDescriptorIdentityError(f"{path} contains a non-finite float")
        return value
    if value_type in (dict, _MAPPING_PROXY_TYPE):
        result = {}
        for key, item in value.items():
            if type(key) is not str:
                raise RuntimeDescriptorIdentityError(
                    f"{path} contains a non-string object key {key!r}"
                )
            result[key] = _canonical_json_value(item, path=f"{path}.{key}")
        return result
    if value_type in (list, tuple):
        return [
            _canonical_json_value(item, path=f"{path}[{index}]")
            for index, item in enumerate(value)
        ]
    if isinstance(value, Mapping):
        result = {}
        for key, item in value.items():
            if type(key) is not str:
                raise RuntimeDescriptorIdentityError(
                    f"{path} contains a non-string object key {key!r}"
                )
            result[key] = _canonical_json_value(
                item,
                path=f"{path}.{key}",
            )
        return result
    if isinstance(value, (list, tuple)):
        return [
            _canonical_json_value(item, path=f"{path}[{index}]")
            for index, item in enumerate(value)
        ]
    raise RuntimeDescriptorIdentityError(
        f"{path} contains unsupported value type {type(value).__name__}"
    )


def canonical_runtime_descriptor_json(
    descriptor: Mapping[str, Any],
) -> str:
    """Return the domain/schema-tagged canonical descriptor payload.

    ``variant_key`` is added by the runtime index resolver after compilation.
    It is the sole root field outside compiler authority; every other emitted
    field, including the logical ``program`` alias, participates in identity.
    """

    if not isinstance(descriptor, Mapping):
        raise RuntimeDescriptorIdentityError("runtime descriptor must be an object")
    canonical = _canonical_json_value(
        descriptor,
        path="runtime_descriptor",
    )
    canonical.pop("variant_key", None)
    return json.dumps(
        {
            "descriptor": canonical,
            "domain": RUNTIME_DESCRIPTOR_DIGEST_DOMAIN,
            "schema_version": RUNTIME_DESCRIPTOR_DIGEST_SCHEMA_VERSION,
        },
        allow_nan=False,
        ensure_ascii=True,
        sort_keys=True,
        separators=(",", ":"),
    )


def runtime_descriptor_sha256(descriptor: Mapping[str, Any]) -> str:
    """Hash the complete compiler-owned runtime descriptor contract."""

    payload = canonical_runtime_descriptor_json(descriptor).encode("ascii")
    return hashlib.sha256(payload).hexdigest()


__all__ = [
    "PACKED_TAPE_ENCODING",
    "PACKED_TAPE_MAX_BYTES",
    "PACKED_TAPE_SCHEMA_VERSION",
    "RUNTIME_DESCRIPTOR_DIGEST_DOMAIN",
    "RUNTIME_DESCRIPTOR_DIGEST_SCHEMA_VERSION",
    "RuntimeDescriptorIdentityError",
    "canonical_runtime_descriptor_json",
    "expand_runtime_descriptor_tape",
    "pack_runtime_descriptor_tape",
    "runtime_descriptor_sha256",
]
